import logging
from urllib3.exceptions import ConnectTimeoutError
from taf.hw.pdu.exceptions import PduConnectionError


def try_perform_operation_on_pdu(operation, tries=3, **kwargs):
    attempt = 1
    while attempt <= tries:
        try:
            logging.debug(f"[PDU] Trying to perform operation: {operation.__name__} - attempt number {attempt}")
            return operation(**kwargs)
        except (PduConnectionError, ConnectTimeoutError) as e:
            attempt = attempt + 1
            if tries:
                logging.warning("[PDU] Connection issue: {}".format(repr(e)))
            else:
                raise e
